const assets={"/index.html":{"body":"<!doctype html><html lang=\"zh-Hant\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>山野氣象站｜露營天氣監控</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f5f6f2;color:#203c34;font-family:\"DM Sans\",\"Noto Sans TC\",system-ui,sans-serif}header,main{max-width:1180px;margin:auto;padding:0 28px}header{height:70px;display:flex;align-items:center;gap:12px;font-size:21px;font-weight:800}header small{margin-left:auto;font-size:14px;color:#586d62}.logo{background:#214d3f;color:white;padding:5px 9px;border-radius:9px}main{padding-bottom:40px}.hero{isolation:isolate;position:relative;overflow:hidden;background:#20483c;border-radius:18px;color:#fff9e7;padding:38px 34px;min-height:184px}.hero canvas{position:absolute;inset:0;width:100%;height:100%;z-index:-1}.hero h1{font-size:clamp(33px,5vw,54px);margin:6px 0;letter-spacing:.04em}.hero p{margin:0;color:#e4eadc}.eyebrow{font:700 12px/1.5 monospace;letter-spacing:.18em;color:#d4e5aa}.box,form,.metric{background:#fff;border:1px solid #dce2d9;border-radius:14px}form{display:flex;align-items:end;flex-wrap:wrap;gap:14px;padding:20px;margin:16px 0}label{font-weight:650;font-size:15px;display:grid;gap:6px}.place{flex:1;min-width:min(235px,100%)}input,button,select{font:inherit;border-radius:8px;padding:10px 12px;border:1px solid #cdd7cd;background:white;color:inherit;min-height:44px;max-width:100%}button{cursor:pointer;font-weight:650}button:hover{background:#e8eee5}.primary{background:#264f40;color:white;border-color:#264f40}.primary:hover{background:#38644f}#searchInfo:empty,#choices:empty{display:none}#choices{display:flex;flex-wrap:wrap;gap:6px}h2{font-size:23px;margin:0}h3{margin:0}.heading{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:24px 0 12px}.meta,footer{font-size:14px;color:#596c60}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{padding:18px;border-top:3px solid var(--a)}.icon{font-size:22px;color:var(--a);display:inline-grid;place-items:center;background:var(--bg);border-radius:10px;width:36px;height:36px;margin-right:8px}.value{font-size:36px;font-weight:700;line-height:1.5}.unit{font-size:16px;margin-left:5px;color:#63736b}.box{padding:20px;margin-top:16px}.hourHead{display:flex;align-items:center;gap:12px}.hourHead output{font-size:1.55rem;font-weight:750;color:#245b46;font-variant-numeric:tabular-nums}#hour{width:100%;padding:0;margin:4px 0 0;cursor:pointer;accent-color:#275e49;display:block}#ticks{position:relative;margin:0 9px 22px;height:20px;font:14px/1.3 system-ui;color:#566b5f}#ticks span{position:absolute;transform:translateX(-50%)}#ticks span:first-child{transform:none}#ticks span:last-child{transform:translateX(-100%)}#forecastMetrics .metric{background:#f8faf6}a{color:#295f4c}.quake{border-left:5px solid #809176}.alert{border-left-color:#cb741c;background:#fff8eb}footer{margin-top:18px}p{line-height:1.55}#coords{overflow-wrap:anywhere}@media(max-width:720px){header,main{padding-left:15px;padding-right:15px}.hero{padding:26px 18px}.metrics{grid-template-columns:1fr 1fr}.metric{padding:13px}form{gap:10px}.place{flex-basis:100%}header small{font-size:12px}.hero p{max-width:210px}.box{padding:14px}}\n.fine{display:flex;gap:8px;margin:0 0 14px}.fine button:disabled{opacity:.45;cursor:default}#dates{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-bottom:16px}#dates button{padding:6px 2px;font-variant-numeric:tabular-nums}#dates button[aria-pressed=true]{color:white;background:#265140;border-color:#265140}.hourHead{flex-wrap:wrap;margin:8px 0}.hourHead output{font-size:clamp(16px,3vw,24px)}#phase{border-radius:14px;padding:3px 10px;font-size:14px;font-weight:650}.sun{background:#f4cf76;color:#61410a}.moon{background:#48597c;color:white}#bands{display:flex;margin:14px 8px 0;overflow:hidden;border-radius:5px;background:#ddd}#bands i{flex:1;height:12px}#ticks{display:block;position:relative;margin:0 8px 12px;font-variant-numeric:tabular-nums}#ticks small:first-child{transform:none}#ticks small:last-child{transform:translateX(-100%)}#ticks small{position:absolute;transform:translateX(-50%);font-size:clamp(10px,2.8vw,13px)}#hour{margin-top:-2px}</style><header><span class=\"logo\" aria-hidden=\"true\">⌁</span>山野氣象站<small>露營天氣監控</small></header><main><div class=\"hero\"><canvas id=\"art\"></canvas><span class=\"eyebrow\">CAMP WEATHER</span><h1>營地天氣總覽</h1><p>掌握山間風雨，安排這一趟露營。</p></div>\n<form id=\"form\"><label class=\"place\">營區位置<input id=\"place\" placeholder=\"營區名稱、Google 地圖網址或座標\" required></label><button type=\"button\" id=\"maps\">Google 地圖搜尋</button><button type=\"button\" id=\"gps\">◎ 目前位置</button><label>露營日期<input type=\"date\" id=\"day\" required></label><button class=\"primary\">查詢天氣</button></form><p role=\"status\" id=\"searchInfo\"></p><div id=\"choices\"></div>\n<div class=\"heading\"><h2>目前天氣</h2><span id=\"coords\" class=\"meta\">等待設定營區</span></div><div class=\"metrics\" id=\"metrics\"></div><p class=\"meta\" role=\"status\" id=\"weatherStatus\">選定位置後開始監控。</p>\n<section class=\"box\"><h2>五日逐時預報</h2><p id=\"forecastInfo\" class=\"meta\">選擇露營日期，查看連續多日的逐時變化。</p><div id=\"timeline\" hidden><div id=\"dates\" role=\"group\" aria-label=\"預報日期\"></div><div class=\"hourHead\"><label for=\"hour\">預報時段</label><output id=\"hourText\" for=\"hour\"></output><span id=\"phase\"></span></div><div id=\"bands\" aria-hidden=\"true\"></div><input id=\"hour\" type=\"range\" min=\"0\" max=\"23\" step=\"1\" value=\"0\" aria-label=\"選擇預報時段\"><div id=\"ticks\" aria-hidden=\"true\"></div><div class=\"fine\"><button id=\"earlier\" type=\"button\">前一小時</button><button id=\"later\" type=\"button\">後一小時</button></div><div class=\"metrics\" id=\"forecastMetrics\"></div></div></section>\n<section id=\"quake\" class=\"box quake\" aria-live=\"polite\"><h2>周邊地震提醒</h2><p class=\"meta\">最近 7 天 · 營區半徑 100 公里 · USGS 收錄事件</p><div id=\"events\">等待設定營區</div><p><a href=\"https://www.cwa.gov.tw/V8/C/E/index.html\" target=\"_blank\" rel=\"noopener\">查看中央氣象署地震報告</a>　<a href=\"https://alerts.ncdr.nat.gov.tw/\" target=\"_blank\" rel=\"noopener\">查看台灣災防告警</a></p></section>\n<footer>天氣資料 © <a href=\"https://open-meteo.com/\">Open-Meteo</a> · 地點搜尋 © OpenStreetMap contributors · 頁面開啟時每 5 分鐘重新查詢</footer></main><script src=\"art.js\"></script><script src=\"app.js\"></script></html>\n","type":"text/html; charset=utf-8"},"/app.js":{"body":"'use strict';\nconst el=id=>document.getElementById(id);\nconst fields=[\n ['wind_speed_10m','蒲福風級','級','≋','#37866e','#e4f1e9'],\n ['rain','雨量','mm','☂','#387caf','#e4eff8'],\n ['temperature_2m','氣溫','°C','☀','#ba762d','#faf0dc'],\n ['relative_humidity_2m','相對濕度','%','◉','#6177a3','#eceff8']\n];\nlet active=null,generation=0,searchId=0,lastRefresh=0;\nconst today=new Date();\nfunction localDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}\nconst end=new Date(today);end.setDate(end.getDate()+4);\nel('day').min=localDate(today);el('day').max=localDate(end);\nel('day').value=localDate(today);\nfunction stamp(){return new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}\nfunction beaufort(speed){\n if(!Number.isFinite(speed)||speed<0)return '—';\n if(speed>=61.3)return '>17';\n const thresholds=[0.3,1.6,3.4,5.5,8,10.8,13.9,17.2,20.8,24.5,28.5,32.7,37,41.5,46.2,51,56.1];\n return thresholds.filter(limit=>speed>=limit).length;\n}\nfunction showMetrics(data={},target='metrics'){el(target).replaceChildren(...fields.map(([key,label,unit,symbol,color,bg])=>{const card=document.createElement('div');card.className='metric';card.style.setProperty('--a',color);card.style.setProperty('--bg',bg);card.innerHTML='<span class=\"icon\"></span><b></b><div><span class=\"value\"></span><span class=\"unit\"></span></div>';[symbol,label,key==='wind_speed_10m'?beaufort(data[key]):num(data[key]),unit].forEach((v,i)=>card.querySelectorAll('.icon,b,.value,.unit')[i].textContent=v);return card}))}\nfunction num(v){return Number.isFinite(v)?String(v):'—'}\nasync function json(url,params){const u=new URL(url);u.search=new URLSearchParams(params);const r=await fetch(u,{signal:AbortSignal.timeout(16000)});if(!r.ok)throw Error(r.status);return r.json()}\nfunction parseCoords(s){const match=s.trim().match(/^([+-]?\\d+(?:\\.\\d+)?)\\s*[,，]\\s*([+-]?\\d+(?:\\.\\d+)?)$/);if(!match)return null;const lat=Number(match[1]),lon=Number(match[2]);if(Math.abs(lat)>90||Math.abs(lon)>180)throw Error('緯度需介於 −90～90，經度需介於 −180～180。');return {lat,lon,name:s.trim()}}\nfunction distance(lat,lon,a,b){const rad=Math.PI/180,x=Math.sin((a-lat)*rad/2)**2+Math.cos(lat*rad)*Math.cos(a*rad)*Math.sin((b-lon)*rad/2)**2;return Math.round(12742*Math.asin(Math.min(1,Math.sqrt(x))))}\nfunction choose(p){active=p;el('place').value=p.name;el('choices').replaceChildren();el('searchInfo').textContent='';try{localStorage.setItem('camp-trip',JSON.stringify({...p,date:el('day').value}))}catch{}refresh()}\nfunction mapURL(text){\n const token=text.match(/https?:\\/\\/[^\\s<>\"「」]+/i)?.[0];\n if(!token)return null;\n const u=new URL(token);\n const host=u.hostname;\n const short=host==='maps.app.goo.gl'||(host==='goo.gl'&&u.pathname.startsWith('/maps/'));\n const google=/^(?:(?:maps|www)\\.)?google\\.(?:com|com\\.tw|[a-z]{2}|co\\.(?:jp|uk|nz)|com\\.au)$/.test(host);\n if(u.username||u.password||u.port||(!short&&!(google&&(host.startsWith('maps.')||/^\\/maps(?:\\/|$)/.test(u.pathname)))))throw Error('地圖網址請使用 Google 地圖的分享連結。');\n u.protocol='https:';\n return {u,short};\n}\nfunction mapLocation(u){\n const path=decodeURIComponent(u.pathname);\n const title=path.match(/\\/maps\\/(?:place|search)\\/([^/]+)/)?.[1]?.replace(/\\+/g,' ');\n const pin=Array.from((path+u.searchParams.get('data')).matchAll(/!3d(-?\\d+(?:\\.\\d+)?)!4d(-?\\d+(?:\\.\\d+)?)/g)).at(-1);\n const query=u.searchParams.get('query')||u.searchParams.get('q')||u.searchParams.get('destination');\n const coords=pin?parseCoords(pin[1]+','+pin[2]):parseCoords((query||title||'').replace(/^loc:/,''));\n if(coords)return {coords:{...coords,name:title||coords.name}};\n if(query||title)return {query:query||title};\n const center=path.match(/@(-?\\d+(?:\\.\\d+)?),(-?\\d+(?:\\.\\d+)?)/);\n if(center)return {center:parseCoords(center[1]+','+center[2])};\n throw Error('地圖連結沒有可辨識的營區位置。請在 Google 地圖點選營區圖釘後重新分享，或貼上座標。');\n}\nel('maps').onclick=()=>{\n const q=el('place').value.trim();\n try{\n  const map=mapURL(q);\n  const target=new URL('https://www.google.com/maps/search/');\n  target.search=new URLSearchParams({api:'1',query:q||'露營區'});\n  window.open(map?map.u.href:target.href,'_blank','noopener,noreferrer');\n  el('searchInfo').textContent='在 Google 地圖選好營區後，點「分享」複製連結，再貼回營區位置欄。';\n }catch{el('searchInfo').textContent='請輸入營區名稱，或貼上 Google 地圖分享連結。'}\n};\n\nasync function search(e){e.preventDefault();const id=++searchId;let q=el('place').value.trim();el('choices').replaceChildren();try{\n const map=mapURL(q);\n if(map){\n  let u=map.u;\n  if(map.short){\n   el('searchInfo').textContent='正在讀取 Google 地圖分享連結…';\n   try{const r=await json(location.origin+'/api/map-link',{url:u.href});u=mapURL(r.url).u}\n   catch{throw Error('地圖短網址暫時無法展開。請開啟 Google 地圖後複製完整網址，或貼上營區座標。')}\n   if(id!==searchId)return;\n  }\n  const point=mapLocation(u);\n  if(point.coords)return choose(point.coords);\n  if(point.center){\n   el('searchInfo').textContent='這個網址只包含地圖中心。請確認此處就是營區。';\n   const b=document.createElement('button');b.textContent='使用地圖中心 '+point.center.name;b.onclick=()=>choose(point.center);el('choices').append(b);return;\n  }\n  q=point.query;\n }\n const coords=parseCoords(q);if(coords)return choose(coords);if(active?.name===q)return choose(active);el('searchInfo').textContent='正在尋找營區…';const data=await json('https://nominatim.openstreetmap.org/search',{q,format:'jsonv2',limit:5,'accept-language':'zh-TW'});if(id!==searchId)return;el('searchInfo').textContent=data.length?'請選擇正確的營區位置。':'找不到這個地點。請貼上地圖上的緯度、經度，或使用目前位置。';data.forEach(v=>{const b=document.createElement('button');b.textContent=v.display_name;b.onclick=()=>choose({name:v.display_name,lat:+v.lat,lon:+v.lon});el('choices').append(b)})}catch(err){if(id===searchId)el('searchInfo').textContent=/^(緯度|地圖)/.test(err.message)?err.message:'地名搜尋暫時無法連線。可直接貼上緯度、經度查詢。'}}\nlet hourlySamples=[];\nlet selectedTime='';\nfunction displayHour(){\n const sample=hourlySamples[Number(el('hour').value)];\n if(!sample)return;\n selectedTime=sample.time;\n const hour=selectedTime.replace('T',' ');\n\n el('earlier').disabled=Number(el('hour').value)===0;\n el('later').disabled=Number(el('hour').value)===hourlySamples.length-1;\n el('hourText').textContent=hour;\n el('phase').textContent=sample.daylight===1?'☀ 白天':sample.daylight===0?'☾ 夜晚':'日夜資料待更新';\n el('phase').className=sample.daylight===1?'sun':sample.daylight===0?'moon':'';\n for(const button of el('dates').children){\n  button.setAttribute('aria-pressed',String(button.dataset.date===selectedTime.slice(0,10)));\n }\n el('hour').setAttribute('aria-valuetext',hour);\n showMetrics(sample,'forecastMetrics');\n}\nel('hour').addEventListener('input',displayHour);\nfor(const [button,delta] of [['earlier',-1],['later',1]]){\n el(button).onclick=()=>{el('hour').value=Number(el('hour').value)+delta;displayHour()};\n}\nfunction setForecast(hourly,date,currentTime){\n const todayKey=currentTime.slice(0,10);\n const dates=[...new Set(hourly.time.map(time=>time.slice(0,10)))].filter(key=>key>=todayKey);\n if(!dates.length)return false;\n el('day').min=dates[0];\n el('day').max=dates.at(-1);\n if(!dates.includes(date))return false;\n el('dates').replaceChildren();\n for(const dateKey of dates){\n  const button=document.createElement('button');\n  button.type='button';\n  button.dataset.date=dateKey;\n  button.textContent=dateKey.slice(5).replace('-','/');\n  button.onclick=()=>{\n   el('day').value=dateKey;\n   selectedTime='';\n   setForecast(hourly,dateKey,currentTime);\n  };\n  el('dates').append(button);\n }\n const anchor=date+'T'+currentTime.slice(11,13)+':00';\n let center=hourly.time.indexOf(anchor);\n if(center<0)center=hourly.time.findIndex(time=>time.startsWith(date)&&time>=anchor);\n if(center<0)return false;\n const start=Math.max(0,center-3);\n hourlySamples=hourly.time.slice(start,center+25).map((time,i)=>{\n  const sample={time,daylight:hourly.is_day?.[start+i]};\n  for(const [key] of fields)sample[key]=hourly[key][start+i];\n  return sample;\n });\n const last=hourlySamples.length-1;\n const saved=hourlySamples.findIndex(s=>s.time===selectedTime);\n el('hour').max=last;\n el('hour').value=saved>=0?saved:center-start;\n el('bands').replaceChildren();\n el('ticks').replaceChildren();\n hourlySamples.forEach((sample,i)=>{\n  const segment=document.createElement('i');\n  segment.className=sample.daylight===1?'sun':sample.daylight===0?'moon':'';\n  if(sample.time.endsWith('T00:00'))segment.style.borderLeft='2px solid white';\n  el('bands').append(segment);\n  if(i!==0&&i!==last&&(i%6!==0||last-i<3))return;\n  const tick=document.createElement('small');\n  tick.textContent=sample.time.slice(11,13)+'時';\n  tick.style.left=(100*i/Math.max(last,1))+'%';\n  el('ticks').append(tick);\n });\n displayHour();\n el('timeline').hidden=false;\n return true;\n}\nasync function refresh(){\n if(!active)return;const id=++generation,{lat,lon,name}=active,date=el('day').value;lastRefresh=Date.now();\n el('coords').textContent=name+' · '+lat.toFixed(4)+', '+lon.toFixed(4);showMetrics();el('timeline').hidden=true;el('events').textContent='查詢地震目錄中…';el('quake').classList.remove('alert');el('weatherStatus').textContent='正在取得最新天氣…';el('forecastInfo').textContent=date+' · 查詢中…';\n const vars=fields.map(f=>f[0]).join(',');\n await Promise.allSettled([weather(),quakes()]);\n async function weather(){try{const d=await json('https://api.open-meteo.com/v1/forecast',{latitude:lat,longitude:lon,current:vars,hourly:vars+',is_day',wind_speed_unit:'ms',past_days:1,forecast_days:5,timezone:'auto'});if(id!==generation)return;const h=d.hourly;const count=setForecast(h,date,d.current.time);showMetrics(d.current);el('weatherStatus').textContent='模式估計時間 '+d.current.time.replace('T',' ')+'（'+d.timezone+'） · 雨量為前 '+Math.round(d.current.interval/60)+' 分鐘累積 · '+stamp()+' 已查詢';el('forecastInfo').textContent=count?'前 3 小時至後 24 小時 · 以所選日期的營區當地目前整點為基準 · 雨量為前一小時累積':date+' 超出可查詢期間。可用預報為 '+el('day').min+' 至 '+h.time.at(-1).slice(0,10)+'。'}catch{if(id!==generation)return;el('weatherStatus').textContent='天氣資料暫時無法取得，可重新按「查詢天氣」。';el('forecastInfo').textContent='逐時預報暫時無法取得。'}}\n async function quakes(){try{const d=await json('https://earthquake.usgs.gov/fdsnws/event/1/query',{format:'geojson',latitude:lat,longitude:lon,maxradiuskm:100,eventtype:'earthquake',starttime:new Date(Date.now()-7*86400000).toISOString(),orderby:'time'});if(id!==generation)return;const list=d.features;el('events').textContent=list.length?'附近有 '+list.length+' 起地震紀錄，最新事件如下。':'近 7 天查無符合範圍的 USGS 地震紀錄。';el('quake').classList.toggle('alert',list.length>0);list.slice(0,5).forEach(f=>{const p=document.createElement('p'),[x,y,z]=f.geometry.coordinates,v=f.properties;p.textContent='M '+num(v.mag)+'　距營區 '+distance(lat,lon,y,x)+' 公里 · 深度 '+num(z)+' 公里 · '+new Date(v.time).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false})+'（台灣時間）';el('events').append(p)});el('events').append(document.createElement('br'),'查詢時間 '+stamp()+'。實際災情請查閱官方告警。')}catch{if(id===generation)el('events').textContent='地震服務暫時無法連線，周邊狀況未知。請查看下方官方報告。'}}\n}\nel('form').onsubmit=search;el('place').oninput=()=>{searchId++;el('choices').replaceChildren();el('searchInfo').textContent=''};\nel('day').onchange=()=>{selectedTime='';if(active&&el('place').value===active.name&&el('day').value)choose(active)};\nel('gps').onclick=()=>{const id=++searchId;el('choices').replaceChildren();el('searchInfo').textContent='正在定位…';const fail=()=>{if(id===searchId)el('searchInfo').textContent='無法取得定位，請輸入營區名稱或座標。'};if(!navigator.geolocation)return fail();navigator.geolocation.getCurrentPosition(p=>{if(id===searchId)choose({lat:p.coords.latitude,lon:p.coords.longitude,name:'目前位置'})},fail,{timeout:12000})};\nshowMetrics();try{const p=JSON.parse(localStorage.getItem('camp-trip'));if(p&&Number.isFinite(p.lat)&&Number.isFinite(p.lon)){if(p.date>=el('day').min&&p.date<=el('day').max)el('day').value=p.date;choose(p)}}catch{}\nfunction tick(){if(!document.hidden&&Date.now()-lastRefresh>=300000)refresh()}setInterval(tick,30000);document.addEventListener('visibilitychange',tick);\n","type":"text/javascript; charset=utf-8"},"/art.js":{"body":"function landscape(){\nconst c=document.querySelector('#art'),w=c.clientWidth,h=c.clientHeight;if(!w)return;c.width=w*2;c.height=h*2;const g=c.getContext('2d');g.scale(2,2);\nconst sky=g.createLinearGradient(0,0,w,h);sky.addColorStop(0,'#193f35');sky.addColorStop(.56,'#63806e');sky.addColorStop(1,'#edc78b');g.fillStyle=sky;g.fillRect(0,0,w,h);\ng.fillStyle='#f4d793';g.beginPath();g.arc(w*.83,h*.32,h*.15,0,7);g.fill();\nfunction polygon(points,color){g.fillStyle=color;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill()}\nfor(let j=0;j<3;j++){const pts=[[0,h]];for(let i=0;i<=65;i++){const x=i/65;pts.push([x*w,h*(.54+.12*j+.13*Math.sin(x*15+j*2)+.07*Math.sin(x*31+j)+.023*Math.sin(i*2+j))])}pts.push([w,h]);polygon(pts,['#829783','#526f60','#314f43'][j])}\nfor(let i=0;i<70;i++){const x=i*w/68,y=h*(.95+.04*Math.sin(i)),s=h*(.09+.12*(1+Math.sin(i*52))/2);for(let j=0;j<3;j++)polygon([[x,y-s+j*s*.20],[x-s*(.12+j*.055),y-s*.48+j*s*.26],[x+s*(.12+j*.055),y-s*.48+j*s*.26]],'#284a3c')}\npolygon([[0,h],[w*.66,h*.96],[w*.81,h*.89],[w,h*.94],[w,h]],'#19392e');let x=w*.81,y=h*.92,s=h*.24;polygon([[x-s,y],[x-s*.1,y-s],[x+s*.9,y]],'#e9ae58');polygon([[x-s*.1,y-s],[x+s*.9,y],[x+s*1.55,y-4],[x+s*.55,y-s*.92]],'#be8645');polygon([[x-s*.6,y],[x-s*.1,y-s*.72],[x+s*.48,y]],'#483e2e');const shade=g.createLinearGradient(0,0,w*.7,0);shade.addColorStop(0,'#193c34');shade.addColorStop(1,'transparent');g.fillStyle=shade;g.fillRect(0,0,w,h)}\nnew ResizeObserver(landscape).observe(document.querySelector('#art'));\n","type":"text/javascript; charset=utf-8"},"/":{"body":"<!doctype html><html lang=\"zh-Hant\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>山野氣象站｜露營天氣監控</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f5f6f2;color:#203c34;font-family:\"DM Sans\",\"Noto Sans TC\",system-ui,sans-serif}header,main{max-width:1180px;margin:auto;padding:0 28px}header{height:70px;display:flex;align-items:center;gap:12px;font-size:21px;font-weight:800}header small{margin-left:auto;font-size:14px;color:#586d62}.logo{background:#214d3f;color:white;padding:5px 9px;border-radius:9px}main{padding-bottom:40px}.hero{isolation:isolate;position:relative;overflow:hidden;background:#20483c;border-radius:18px;color:#fff9e7;padding:38px 34px;min-height:184px}.hero canvas{position:absolute;inset:0;width:100%;height:100%;z-index:-1}.hero h1{font-size:clamp(33px,5vw,54px);margin:6px 0;letter-spacing:.04em}.hero p{margin:0;color:#e4eadc}.eyebrow{font:700 12px/1.5 monospace;letter-spacing:.18em;color:#d4e5aa}.box,form,.metric{background:#fff;border:1px solid #dce2d9;border-radius:14px}form{display:flex;align-items:end;flex-wrap:wrap;gap:14px;padding:20px;margin:16px 0}label{font-weight:650;font-size:15px;display:grid;gap:6px}.place{flex:1;min-width:min(235px,100%)}input,button,select{font:inherit;border-radius:8px;padding:10px 12px;border:1px solid #cdd7cd;background:white;color:inherit;min-height:44px;max-width:100%}button{cursor:pointer;font-weight:650}button:hover{background:#e8eee5}.primary{background:#264f40;color:white;border-color:#264f40}.primary:hover{background:#38644f}#searchInfo:empty,#choices:empty{display:none}#choices{display:flex;flex-wrap:wrap;gap:6px}h2{font-size:23px;margin:0}h3{margin:0}.heading{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:24px 0 12px}.meta,footer{font-size:14px;color:#596c60}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric{padding:18px;border-top:3px solid var(--a)}.icon{font-size:22px;color:var(--a);display:inline-grid;place-items:center;background:var(--bg);border-radius:10px;width:36px;height:36px;margin-right:8px}.value{font-size:36px;font-weight:700;line-height:1.5}.unit{font-size:16px;margin-left:5px;color:#63736b}.box{padding:20px;margin-top:16px}.hourHead{display:flex;align-items:center;gap:12px}.hourHead output{font-size:1.55rem;font-weight:750;color:#245b46;font-variant-numeric:tabular-nums}#hour{width:100%;padding:0;margin:4px 0 0;cursor:pointer;accent-color:#275e49;display:block}#ticks{position:relative;margin:0 9px 22px;height:20px;font:14px/1.3 system-ui;color:#566b5f}#ticks span{position:absolute;transform:translateX(-50%)}#ticks span:first-child{transform:none}#ticks span:last-child{transform:translateX(-100%)}#forecastMetrics .metric{background:#f8faf6}a{color:#295f4c}.quake{border-left:5px solid #809176}.alert{border-left-color:#cb741c;background:#fff8eb}footer{margin-top:18px}p{line-height:1.55}#coords{overflow-wrap:anywhere}@media(max-width:720px){header,main{padding-left:15px;padding-right:15px}.hero{padding:26px 18px}.metrics{grid-template-columns:1fr 1fr}.metric{padding:13px}form{gap:10px}.place{flex-basis:100%}header small{font-size:12px}.hero p{max-width:210px}.box{padding:14px}}\n.fine{display:flex;gap:8px;margin:0 0 14px}.fine button:disabled{opacity:.45;cursor:default}#dates{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-bottom:16px}#dates button{padding:6px 2px;font-variant-numeric:tabular-nums}#dates button[aria-pressed=true]{color:white;background:#265140;border-color:#265140}.hourHead{flex-wrap:wrap;margin:8px 0}.hourHead output{font-size:clamp(16px,3vw,24px)}#phase{border-radius:14px;padding:3px 10px;font-size:14px;font-weight:650}.sun{background:#f4cf76;color:#61410a}.moon{background:#48597c;color:white}#bands{display:flex;margin:14px 8px 0;overflow:hidden;border-radius:5px;background:#ddd}#bands i{flex:1;height:12px}#ticks{display:block;position:relative;margin:0 8px 12px;font-variant-numeric:tabular-nums}#ticks small:first-child{transform:none}#ticks small:last-child{transform:translateX(-100%)}#ticks small{position:absolute;transform:translateX(-50%);font-size:clamp(10px,2.8vw,13px)}#hour{margin-top:-2px}</style><header><span class=\"logo\" aria-hidden=\"true\">⌁</span>山野氣象站<small>露營天氣監控</small></header><main><div class=\"hero\"><canvas id=\"art\"></canvas><span class=\"eyebrow\">CAMP WEATHER</span><h1>營地天氣總覽</h1><p>掌握山間風雨，安排這一趟露營。</p></div>\n<form id=\"form\"><label class=\"place\">營區位置<input id=\"place\" placeholder=\"營區名稱、Google 地圖網址或座標\" required></label><button type=\"button\" id=\"maps\">Google 地圖搜尋</button><button type=\"button\" id=\"gps\">◎ 目前位置</button><label>露營日期<input type=\"date\" id=\"day\" required></label><button class=\"primary\">查詢天氣</button></form><p role=\"status\" id=\"searchInfo\"></p><div id=\"choices\"></div>\n<div class=\"heading\"><h2>目前天氣</h2><span id=\"coords\" class=\"meta\">等待設定營區</span></div><div class=\"metrics\" id=\"metrics\"></div><p class=\"meta\" role=\"status\" id=\"weatherStatus\">選定位置後開始監控。</p>\n<section class=\"box\"><h2>五日逐時預報</h2><p id=\"forecastInfo\" class=\"meta\">選擇露營日期，查看連續多日的逐時變化。</p><div id=\"timeline\" hidden><div id=\"dates\" role=\"group\" aria-label=\"預報日期\"></div><div class=\"hourHead\"><label for=\"hour\">預報時段</label><output id=\"hourText\" for=\"hour\"></output><span id=\"phase\"></span></div><div id=\"bands\" aria-hidden=\"true\"></div><input id=\"hour\" type=\"range\" min=\"0\" max=\"23\" step=\"1\" value=\"0\" aria-label=\"選擇預報時段\"><div id=\"ticks\" aria-hidden=\"true\"></div><div class=\"fine\"><button id=\"earlier\" type=\"button\">前一小時</button><button id=\"later\" type=\"button\">後一小時</button></div><div class=\"metrics\" id=\"forecastMetrics\"></div></div></section>\n<section id=\"quake\" class=\"box quake\" aria-live=\"polite\"><h2>周邊地震提醒</h2><p class=\"meta\">最近 7 天 · 營區半徑 100 公里 · USGS 收錄事件</p><div id=\"events\">等待設定營區</div><p><a href=\"https://www.cwa.gov.tw/V8/C/E/index.html\" target=\"_blank\" rel=\"noopener\">查看中央氣象署地震報告</a>　<a href=\"https://alerts.ncdr.nat.gov.tw/\" target=\"_blank\" rel=\"noopener\">查看台灣災防告警</a></p></section>\n<footer>天氣資料 © <a href=\"https://open-meteo.com/\">Open-Meteo</a> · 地點搜尋 © OpenStreetMap contributors · 頁面開啟時每 5 分鐘重新查詢</footer></main><script src=\"art.js\"></script><script src=\"app.js\"></script></html>\n","type":"text/html; charset=utf-8"}};
const shortHosts=new Set(['maps.app.goo.gl','goo.gl']);
function isShort(u){
 return u.protocol==='https:'&&!u.port&&!u.username&&!u.password&&shortHosts.has(u.hostname)&&
 (u.hostname==='goo.gl'?/^\/maps\/[\w-]+\/?$/:/^\/[\w-]+\/?$/).test(u.pathname);
}
async function expand(value){
 let u=new URL(value);
 for(let i=0;i<4;i++){
  if(!isShort(u))throw Error();
  const response=await fetch(u,{redirect:'manual',signal:AbortSignal.timeout(5000)});
  const dest=response.headers.get('location');
  if(!dest||response.status<300||response.status>=400)throw Error();
  u=new URL(dest,u);
  if(u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&/^(?:www\.|maps\.)?google\.(?:com|com\.tw|[a-z]{2}|co\.jp|co\.uk|com\.au)$/.test(u.hostname)&&(/^\/maps(?:\/|$)/.test(u.pathname)||u.hostname.startsWith('maps.')))return u.href;
 }
 throw Error();
}
export default {async fetch(request){
 const u=new URL(request.url);
 if(request.method!=='GET')return new Response(null,{status:405});
 if(u.pathname==='/api/map-link'){
  try{return Response.json({url:await expand(u.searchParams.get('url'))})}
  catch{return Response.json({error:'無法展開地圖連結'},{status:400})}
 }
 const asset=Object.hasOwn(assets,u.pathname)&&assets[u.pathname];
 return asset?new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':'no-cache'}}):new Response(null,{status:404});
}};
